<?php
if(PHP_SAPI!=='cli')exit;
require_once dirname(__DIR__).'/app/bootstrap.php';
function demoAttribute(array $p,string $name,string $type='text',bool $variant=false):int{$a=one('SELECT a.id FROM attributes a JOIN category_attributes c ON c.attribute_id=a.id WHERE c.category_id=? AND a.name=?',[$p['category_id'],$name]);if($a)return (int)$a['id'];q('INSERT INTO attributes(name,type,visible,filterable,variant) VALUES(?,?,1,?,?)',[$name,$type,(int)$variant,(int)$variant]);$id=(int)db()->lastInsertId();q('INSERT IGNORE INTO category_attributes VALUES(?,?)',[$p['category_id'],$id]);return $id;}
tx(function(){foreach(['camera'=>['Resolution'=>'24 megapixels'],'laptop'=>['Screen size'=>'14 inches'],'phone'=>['Battery capacity'=>'5000 mAh'],'chair'=>['Material'=>'Mesh and steel'],'drill'=>['Battery capacity'=>'2 Ah'],'rice'=>['Pack weight'=>'5 kg'],'battery'=>['Voltage'=>'12 V','Warranty'=>'Illustrative: configure actual terms']] as $slug=>$values){$p=one('SELECT * FROM products WHERE sku=?',['DEMO-'.strtoupper($slug)]);if(!$p)continue;foreach($values as $name=>$value){$aid=demoAttribute($p,$name);q('INSERT IGNORE INTO product_attribute_values VALUES(?,?,?)',[$p['id'],$aid,$value]);}}
 foreach(['laptop'=>[['RAM','Storage'],[['16 GB','512 GB'],['32 GB','1 TB']]],'phone'=>[['Storage','Color'],[['128 GB','Graphite'],['256 GB','Sage']]]] as $slug=>$spec){$p=one('SELECT * FROM products WHERE sku=?',['DEMO-'.strtoupper($slug)]);if(!$p)continue;$attrs=[];foreach($spec[0] as $name)$attrs[]=demoAttribute($p,$name,$name==='Color'?'color':'dropdown',true);$variants=all('SELECT * FROM product_variants WHERE product_id=? ORDER BY id',[$p['id']]);foreach($variants as $i=>$v){if(!isset($spec[1][$i]))continue;$opts=[];$labels=[];foreach($spec[1][$i] as $j=>$value){q('INSERT IGNORE INTO attribute_options(attribute_id,label,color) VALUES(?,?,?)',[$attrs[$j],$value,$value==='Graphite'?'#303a40':($value==='Sage'?'#7e9380':'')]);$oid=(int)one('SELECT id FROM attribute_options WHERE attribute_id=? AND label=?',[$attrs[$j],$value])['id'];$opts[$attrs[$j]]=$oid;$labels[]=$spec[0][$j].': '.$value;}ksort($opts);q('UPDATE product_variants SET combination=?,label=? WHERE id=?',[json_encode($opts),implode(' / ',$labels),$v['id']]);q('DELETE FROM variant_attribute_values WHERE variant_id=?',[$v['id']]);foreach($opts as $a=>$o)q('INSERT INTO variant_attribute_values VALUES(?,?,?)',[$v['id'],$a,$o]);}foreach(['Memory / storage','Storage / color'] as $old){$r=one('SELECT a.id FROM attributes a JOIN category_attributes ca ON ca.attribute_id=a.id WHERE ca.category_id=? AND a.name=?',[$p['category_id'],$old]);if($r)q('DELETE FROM category_attributes WHERE category_id=? AND attribute_id=?',[$p['category_id'],$r['id']]);}}
});
echo "Demo specification and variant examples enriched.\n";
